-ui-sidebar\",\n        \"@deepseek-ai/dsh-client-ui-theme\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"research\",\n    \"arxiv\",\n    \"latex\",\n    \"zotero\",\n    \"literature\",\n    \"experiment-tracking\"\n  ]\n}\n"
